local Thatcher = {}
local PRODUCTS = {
    thatch_roof = { name = "Slamnata streha", reedCost = 10, time = 5, cost = 50, insulation = 15, description = "Tradicionalna slamnata streha." },
    shingle_roof = { name = "Skodle", woodCost = 8, time = 7, cost = 100, insulation = 20, durability = 60, description = "Lesene skodle." },
    tile_roof = { name = "Strešniki", clayCost = 10, time = 8, cost = 150, insulation = 25, durability = 80, prestige = 3, description = "Glineni strešniki." },
    slate_roof = { name = "Skrilavčeva streha", stoneCost = 12, time = 10, cost = 250, insulation = 30, durability = 90, prestige = 5, description = "Skrilavčeva streha." },
    lead_roof = { name = "Svinčena streha", leadCost = 8, time = 14, cost = 500, insulation = 35, durability = 95, prestige = 10, description = "Svinčena za kraljeve zgradbe." },
    copper_roof = { name = "Bakrena streha", copperCost = 10, time = 20, cost = 1000, insulation = 40, durability = 100, prestige = 20, description = "Bakrena streha — najdražja." },
}
local BUILDINGS = {
    workshop = { name = "Krovna delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    reed_bed = { name = "Tršičnik", cost = { gold = 100, wood = 50 }, upkeep = 2, reedProduction = 5 },
    tile_kiln = { name = "Peč za strešnike", cost = { gold = 800, wood = 200, stone = 300 }, upkeep = 20, qualityBonus = 15 },
    royal_roofing = { name = "Kraljevska krovska", cost = { gold = 4000, wood = 400, stone = 600 }, upkeep = 80, qualityBonus = 35, prestigeBonus = 15 },
}
Thatcher.reedStock = 15; Thatcher.woodStock = 10; Thatcher.clayStock = 10; Thatcher.stoneStock = 8; Thatcher.leadStock = 5; Thatcher.copperStock = 3
Thatcher.productStock = {}; Thatcher.buildings = {}; Thatcher.thatcher = nil; Thatcher.activeMaking = {}; Thatcher.totalProducts = 0; Thatcher.dayTimer = 0
function Thatcher.init() Thatcher.reedStock=15; Thatcher.woodStock=10; Thatcher.clayStock=10; Thatcher.stoneStock=8; Thatcher.leadStock=5; Thatcher.copperStock=3; Thatcher.productStock={}; Thatcher.buildings={}; Thatcher.thatcher=nil; Thatcher.activeMaking={}; Thatcher.totalProducts=0; Thatcher.dayTimer=0; print("[Thatcher] Royal Thatcher & Roofing System initialized (6 products, 4 buildings)") end
function Thatcher.hireThatcher(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Thatcher.thatcher={name=n or ("Krov "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krov najet: %s (spretnost: %d)",Thatcher.thatcher.name,s),"success") end; return true end
function Thatcher.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Thatcher.build(id) local ok,e=Thatcher.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Thatcher.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Thatcher.getQualityBonus() local b=0; for _,bd in ipairs(Thatcher.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Thatcher.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.reedCost and Thatcher.reedStock<(d.reedCost or 0) then return false,"Premalo trstičja" end; if d.woodCost and Thatcher.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clayCost and Thatcher.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.stoneCost and Thatcher.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.leadCost and Thatcher.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.copperCost and Thatcher.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if #Thatcher.buildings==0 then return false,"Potrebna krovna delavnica" end; if not Thatcher.thatcher then return false,"Potreben krov" end; return true end
function Thatcher.make(pt) local ok,e=Thatcher.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.reedCost then Thatcher.reedStock=Thatcher.reedStock-d.reedCost end; if d.woodCost then Thatcher.woodStock=Thatcher.woodStock-d.woodCost end; if d.clayCost then Thatcher.clayStock=Thatcher.clayStock-d.clayCost end; if d.stoneCost then Thatcher.stoneStock=Thatcher.stoneStock-d.stoneCost end; if d.leadCost then Thatcher.leadStock=Thatcher.leadStock-d.leadCost end; if d.copperCost then Thatcher.copperStock=Thatcher.copperStock-d.copperCost end; local t=d.time; if Thatcher.thatcher then t=math.max(1,t-math.floor(Thatcher.thatcher.skill/12)) end; table.insert(Thatcher.activeMaking,{id="roof_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,insulation=d.insulation or 0,durability=d.durability or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krovenje: %s (%d dni)",d.name,t),"info") end; return true end
function Thatcher.completeMaking(m) local q=1.0+(Thatcher.getQualityBonus()/100); if Thatcher.thatcher then q=q+(Thatcher.thatcher.skill/200) end; q=math.min(2.0,q); Thatcher.productStock[m.productType]=(Thatcher.productStock[m.productType] or 0)+1; Thatcher.totalProducts=Thatcher.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if Thatcher.thatcher then Thatcher.thatcher.itemsMade=Thatcher.thatcher.itemsMade+1; if math.random()<0.15 then Thatcher.thatcher.skill=math.min(100,Thatcher.thatcher.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Streha izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Thatcher.update(dt) if not _G.state then return end; Thatcher.dayTimer=Thatcher.dayTimer+dt; if Thatcher.dayTimer>=30 then Thatcher.dayTimer=0; for i=#Thatcher.activeMaking,1,-1 do local m=Thatcher.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Thatcher.completeMaking(m); table.remove(Thatcher.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Thatcher.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Thatcher.thatcher then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Thatcher.getStats() return {reedStock=Thatcher.reedStock,woodStock=Thatcher.woodStock,clayStock=Thatcher.clayStock,stoneStock=Thatcher.stoneStock,productStock=Thatcher.productStock,numBuildings=#Thatcher.buildings,hasThatcher=Thatcher.thatcher~=nil,thatcherName=Thatcher.thatcher and Thatcher.thatcher.name or "—",thatcherSkill=Thatcher.thatcher and Thatcher.thatcher.skill or 0,activeMaking=#Thatcher.activeMaking,totalProducts=Thatcher.totalProducts} end
return Thatcher
